css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .comp-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 9px 36px;}
.mz .comp-fila{display: flex; align-items: center; gap: 10px; justify-content: center;}
.mz .comp-fila .cn{font-size: 20px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 12px; min-width: 70px; text-align: center;}
.mz .comp-fila .caja-sg{width: 44px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .ordenar-bloque{margin-bottom: 10px;}
.mz .banco{display: flex; gap: 9px; margin-bottom: 8px; flex-wrap: wrap;}
.mz .banco .bn{font-size: 18px; font-weight: 700; border: 1.5px dashed #000; border-radius: 8px; padding: 5px 13px; background: #f3f3f3;}
.mz .huecos{display: flex; align-items: center; gap: 7px; flex-wrap: wrap;}
.mz .huecos .hueco-caja{width: 72px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 8px;}
.mz .huecos .flecha{font-size: 17px; font-family: sans-serif;}
.mz .grupo-fila{display: flex; gap: 16px; margin-bottom: 9px;}
.mz .grupo-fila .gn{font-size: 20px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 5px 16px;}
.mz .vf-fila{display: flex; align-items: center; gap: 12px; font-size: 14.5px; font-weight: 600; margin-bottom: 8px;}
.mz .vf-fila .frase{flex: 1; line-height: 1.3;}
.mz .vf-opts{display: flex; gap: 10px; flex-shrink: 0;}
.mz .vf-opts .vf{width: 30px; height: 30px; border: 1.5px solid var(--bosque); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 15px;}
